// Des: Per-tab working directory and inline cd parsing
// Flo: tab cwd map under mutex (key duped once, replace frees old value) > match cd/pushd/cd /d forms > split path from trailing cmd > resolve ~ or path > verify dir exists (typo never runs rest elsewhere)
// I/O: raw cmd + tab id + base cwd (spawn engine) > CdzzResu: dir to run in + cmd left; dir lives in arena, rest points into cmd
// ===================================================================
const std = @import("std"); const stor = @import("store");
const CF = .{ .trim = " \t", .push = "pushd", .cdzz = "cd", .ampe = "&&", .seps = "&|;<>", .drvz = "/d" };
pub const Sess = struct {
mapz: std.StringHashMapUnmanaged([]const u8) = .empty, mute: std.Io.Mutex = .init,
pub fn dein(self: *Sess, allo: std.mem.Allocator) void { var iter = self.mapz.iterator(); while (iter.next()) |entr| { allo.free(entr.key_ptr.*); allo.free(entr.value_ptr.*); } self.mapz.deinit(allo); }
pub fn getz(self: *Sess, iozz: std.Io, tabz_iden: []const u8) !?[]const u8 { try self.mute.lock(iozz); defer self.mute.unlock(iozz); return self.mapz.get(tabz_iden); }
pub fn delz(self: *Sess, allo: std.mem.Allocator, iozz: std.Io, tabz_iden: []const u8) !void { try self.mute.lock(iozz); defer self.mute.unlock(iozz); if (self.mapz.fetchRemove(tabz_iden)) |kvzz| { allo.free(kvzz.key); allo.free(kvzz.value); } }
pub fn setz(self: *Sess, allo: std.mem.Allocator, iozz: std.Io, tabz_iden: []const u8, dirz: []const u8) !void { try self.mute.lock(iozz); defer self.mute.unlock(iozz); const gopz = try self.mapz.getOrPut(allo, tabz_iden); if (gopz.found_existing) { allo.free(gopz.value_ptr.*); } else { gopz.key_ptr.* = try allo.dupe(u8, tabz_iden); } gopz.value_ptr.* = try allo.dupe(u8, dirz); }
};
pub const CdzzKind = enum { none, bare, pure, with_cmdz, badz_dirz };
pub const CdzzResu = struct { kind: CdzzKind, dirz: []const u8, rest: []const u8 };
pub fn cdzzTokeEndz(cmdz: []const u8) ?usize { const trim = std.mem.trimStart(u8, cmdz, CF.trim); const lead = cmdz.len - trim.len; if (std.ascii.startsWithIgnoreCase(trim, CF.push)) { if (trim.len == 5 or trim[5] == ' ' or trim[5] == '\t') return lead + 5; return null; } if (std.ascii.startsWithIgnoreCase(trim, CF.cdzz)) { if (trim.len == 2) return lead + 2; if (trim[2] != ' ' and trim[2] != '\t') return null; const afte = std.mem.trimStart(u8, trim[2..], CF.trim); if (std.ascii.startsWithIgnoreCase(afte, CF.drvz)) { if (afte.len == 2 or afte[2] == ' ' or afte[2] == '\t') { return lead + 2 + (trim[2..].len - afte.len) + 2; } } return lead + 2; } return null; }
pub fn cdzzPars(aren: std.mem.Allocator, iozz: std.Io, cmdz: []const u8, base_cwdz: []const u8) !CdzzResu { const toke_endz = cdzzTokeEndz(cmdz) orelse return .{ .kind = .none, .dirz = base_cwdz, .rest = cmdz }; const afte = std.mem.trim(u8, cmdz[toke_endz..], CF.trim); if (afte.len == 0) return .{ .kind = .bare, .dirz = base_cwdz, .rest = "" }; var targ: []const u8 = undefined; var rest: []const u8 = ""; if (afte[0] == '"' or afte[0] == '\'') { const quot = afte[0]; const clos = std.mem.indexOfScalarPos(u8, afte, 1, quot) orelse return .{ .kind = .none, .dirz = base_cwdz, .rest = cmdz }; targ = afte[1..clos]; rest = std.mem.trim(u8, afte[clos + 1 ..], CF.trim); rest = sepaStri(rest); } else if (std.mem.indexOf(u8, afte, CF.ampe)) |sepz| { targ = std.mem.trim(u8, afte[0..sepz], CF.trim); rest = std.mem.trim(u8, afte[sepz + 2 ..], CF.trim); } else if (std.mem.indexOfAny(u8, afte, CF.seps)) |sepz| { targ = std.mem.trim(u8, afte[0..sepz], CF.trim); rest = sepaStri(std.mem.trim(u8, afte[sepz..], CF.trim)); } else { targ = afte; } if (targ.len == 0) return .{ .kind = .bare, .dirz = base_cwdz, .rest = "" }; var reso: []const u8 = undefined; if (std.mem.eql(u8, targ, "~")) { reso = std.process.Environ.getAlloc(stor.enviLive(), aren, stor.HOME_VARZ) catch base_cwdz; } else { reso = try std.fs.path.resolve(aren, &.{ base_cwdz, targ }); } var dirz = std.Io.Dir.cwd().openDir(iozz, reso, .{}) catch { return .{ .kind = .badz_dirz, .dirz = reso, .rest = "" }; }; dirz.close(iozz); return .{ .kind = if (rest.len == 0) .pure else .with_cmdz, .dirz = reso, .rest = rest }; }
pub fn sepaStri(strz: []const u8) []const u8 { var outz = std.mem.trimStart(u8, strz, CF.trim); if (std.mem.startsWith(u8, outz, CF.ampe)) outz = outz[2..] else if (outz.len > 0 and (outz[0] == '&' or outz[0] == ';' or outz[0] == '|')) outz = outz[1..]; return std.mem.trim(u8, outz, CF.trim); }
